	Data any
}

// Result is the outcome of processing a Job.
type Result struct {
	JobID string
	Err   error
}

// JobPool processes jobs from a channel with a bounded number of workers.
type JobPool struct {
	workers int
	queue   chan Job
	// process handles a single job and returns a Result.
	process func(ctx context.Context, job Job) (Result, error)

	// shutdown coordination
	shutdownOnce sync.Once
	shutdown     chan struct{}
	shutdownDone chan struct{}
	shuttingDown atomic.Bool

	// counters
